/* A STEP LINKED TO A TASK OR A THREAD IS DONE WHEN IT IS. A rule starts this when either moves to done; the row is read
   again first, because the run is queued and a host takes it later, so one reopened in between ticks nothing. A step
   already ticked is left as it is, and nothing is unticked when the work is reopened: a person ticks a step back by hand. */
export default async function run(ctx) {
  const id = ctx.input && ctx.input.id;
  if (!id) return;
  const row = await ctx.record.get(id);
  if (!row || row.fields.state !== 'done') return;
  /* THE FIELD THAT POINTS AT ITS LIST: a ref is matched only against a row of the list it points at. */
  const field = { tasks: 'task', tracks: 'track' }[row.register];
  if (!field) return;
  const open = await ctx.record.list('plan_steps', { all: [{ field, is: row.id }, { none: [{ field: 'done', is: true }] }] });
  for (const step of open) ctx.update('plan_steps#' + step.seq, { done: true }, step.version);
}

/* EVERY PROJECT, FIFTY SEQ NUMBERS AT A TIME. A script's list answers one page of fifty and takes no cursor, so a list
   read whole stopped at fifty projects and a record with more never had the rest brought over. A window of fifty seq
   numbers cannot be cut short, and the walk ends when fewer than a page lie past it. */
async function every(ctx, register) {
  const out = [];
  for (let from = 0; ; from += 50) {
    const rest = await ctx.record.list(register, { field: 'seq', gt: from });
    if (rest.length < 50) return out.concat(rest);
    out.push(...(await ctx.record.list(register, { all: [{ field: 'seq', gt: from }, { field: 'seq', lte: from + 50 }] })));
  }
}

/* THE ONE LINE IS PORTFOLIO'S ABOUT, SINCE project-brief 2.0.0, and a brief written before kept it in One line. Run once
   after the update: each project whose About is empty takes its One line, and a project whose About anybody wrote keeps
   it, with the run saying so where the two differ, since the old line is then drawn nowhere. Run again it finds nothing
   to copy, so a second press changes nothing. */
export default async function run(ctx) {
  for (const project of await every(ctx, 'things')) {
    const line = typeof project.fields.summary === 'string' ? project.fields.summary.trim() : '';
    const about = typeof project.fields.about === 'string' ? project.fields.about.trim() : '';
    if (line === '') continue;
    if (about === '') ctx.update('things#' + project.seq, { about: line }, project.version);
    else if (about !== line) ctx.log(project.fields.name + ' kept its About. Its old one line was: ' + line);
  }
}

/* EVERY ROW OF A LIST, FIFTY SEQ NUMBERS AT A TIME. A script's list answers one page of fifty and takes no cursor, so a
   list read whole stopped at fifty, and a record with more projects, or more steps, was brought over in part or twice.
   A window of fifty seq numbers cannot be cut short, and the walk ends when fewer than a page lie past it. */
async function every(ctx, register, options) {
  const out = [];
  for (let from = 0; ; from += 50) {
    const rest = await ctx.record.list(register, { field: 'seq', gt: from }, options);
    if (rest.length < 50) return out.concat(rest);
    out.push(...(await ctx.record.list(register, { all: [{ field: 'seq', gt: from }, { field: 'seq', lte: from + 50 }] }, options)));
  }
}

/* "title (gain)" as a step and what it gains, split at the bracket that opens the last one, so "Ship it (v2 (beta))"
   gains "v2 (beta)" and "Ship it (v2 (beta)) (first sale)" gains "first sale": every word lands on one side or the other.
   A line that does not end in a bracket, whose last bracket never opens, or that is nothing but one, is all step. */
function split(line) {
  const text = line.trim();
  if (!text.endsWith(')')) return { what: text };
  let depth = 0;
  let at = -1;
  for (let i = text.length - 1; i >= 0 && at < 0; i--) {
    if (text[i] === ')') depth++;
    else if (text[i] === '(' && --depth === 0) at = i;
  }
  const what = at > 0 ? text.slice(0, at).trim() : '';
  if (what === '') return { what: text };
  const gain = text.slice(at + 1, -1).trim();
  return gain === '' ? { what } : { what, gain };
}

/* THE PLAN IS STEPS, SINCE project-brief 2.0.0, and a brief written before kept it as lines of text. Run once after the
   update: each line of a project's old plan becomes a step under it, in the order the lines were written, after any step
   the project already has. A line already made a step, even one since deleted, is passed over, so a second press writes
   nothing twice and a step somebody added first does not keep the rest out. A run stops short of the most a script may
   write and says so, and the next press takes the projects it did not reach. */
export default async function run(ctx) {
  const had = new Map();
  for (const step of await every(ctx, 'plan_steps', { includeDeleted: true })) {
    const at = had.get(step.fields.thing) || { whats: new Set(), rank: 0 };
    at.whats.add(step.fields.what);
    if (typeof step.fields.rank === 'number' && step.fields.rank > at.rank) at.rank = step.fields.rank;
    had.set(step.fields.thing, at);
  }
  let room = 900;
  for (const project of await every(ctx, 'things')) {
    const at = had.get(project.id) || { whats: new Set(), rank: 0 };
    const lines = Array.isArray(project.fields.plan) ? project.fields.plan : [];
    const steps = lines.filter((l) => typeof l === 'string' && l.trim() !== '').map(split).filter((s) => !at.whats.has(s.what));
    if (steps.length === 0) continue;
    if (steps.length > room) {
      ctx.log('Stopped before ' + project.fields.name + '. Run it again to bring over the rest.');
      return;
    }
    steps.forEach((step, i) => ctx.write('plan_steps', { ...step, thing: project.id, rank: at.rank + i + 1, done: false }));
    room -= steps.length;
  }
}
